// SetEmf of the produtoCor to the related item.
// Sets o.R.Emf to related.
// Adds o to related.R.EmfProdutoCors.
func (o *ProdutoCor) SetEmf(ctx context.Context, exec boil.ContextExecutor, insert bool, related *EmpresaFilial) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE `produto_cor` SET %s WHERE %s",
		strmangle.SetParamNames("`", "`", 0, []string{"emf_id"}),
		strmangle.WhereClause("`", "`", 0, produtoCorPrimaryKeyColumns),
	)
	values := []interface{}{related.EmfID, o.CorID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	o.EmfID = related.EmfID
	if o.R == nil {
		o.R = &produtoCorR{
			Emf: related,
		}
	} else {
		o.R.Emf = related
	}

	if related.R == nil {
		related.R = &empresaFilialR{
			EmfProdutoCors: ProdutoCorSlice{o},
		}
	} else {
		related.R.EmfProdutoCors = append(related.R.EmfProdutoCors, o)
	}

	return nil
}

